import { MarkdownEntry } from '../types';
import { parseMarkdownFile } from './filesmdParser';

const STORAGE_KEY = 'nutstore_credentials';
const LOCAL_CACHE_KEY = 'filesmd_cache';
const NUTSTORE_WEBDAV_URL = 'https://dav.jianguoyun.com/dav';
const API_BASE_URL = 'https://nutstore-proxy.etdjok.workers.dev/api';

interface NutstoreCredentials {
  username: string;
  password: string;
}

export function getCredentials(): NutstoreCredentials | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed.username && parsed.password) {
      return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

export function saveCredentials(username: string, password: string): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify({ username, password }));
}

export function clearCredentials(): void {
  localStorage.removeItem(STORAGE_KEY);
  localStorage.removeItem(LOCAL_CACHE_KEY);
}

export function hasCredentials(): boolean {
  return getCredentials() !== null;
}

async function fetchWithTimeout(url: string, options: RequestInit, timeout = 10000): Promise<Response> {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('请求超时，请检查网络连接');
    }
    throw error;
  }
}

export async function testConnectionWithDetails(basePath: string): Promise<{ 
  success: boolean; 
  status?: number; 
  error?: string;
  rootFolders?: string[];
  basePathFiles?: string[];
  basePathFolders?: string[];
  pathResults?: { path: string; status: number; files: string[]; folders: string[] }[];
}> {
  const creds = getCredentials();
  if (!creds) {
    return { success: false, error: '未配置坚果云账号' };
  }

  try {
    const response = await fetchWithTimeout(`${API_BASE_URL}/nutstore/test`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username: creds.username,
        password: creds.password,
        basePath,
      }),
    }, 15000);

    const data = await response.json();
    return data;
  } catch (error) {
    const message = error instanceof Error ? error.message : '连接失败';
    return { success: false, error: message };
  }
}

