function encodePath(pathStr: string): string {
  return pathStr.split('/').map(segment => encodeURIComponent(segment)).join('/');
}

async function makeNutstoreRequest(path: string, options: { method?: string; body?: string; headers?: Record<string, string> } = {}): Promise<Response> {
  const creds = getCredentials();
  if (!creds) {
    throw new Error('未配置坚果云账号');
  }

  const token = btoa(`${creds.username}:${creds.password}`);
  
  const url = `${NUTSTORE_WEBDAV_URL}${encodePath(path)}`;
  
  return fetch(url, {
    method: options.method || 'GET',
    headers: {
      ...options.headers,
      Authorization: `Basic ${token}`,
    },
    body: options.body,
    mode: 'cors',
  });
}

async function parseWebDAVResponse(xmlText: string): Promise<{ href: string }[]> {
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(xmlText, 'application/xml');
    const responseElements = doc.querySelectorAll('response');
    
    return Array.from(responseElements).map(response => {
      const href = response.querySelector('href')?.textContent || '';
      return { href };
    });
  } catch {
    return [];
  }
}

export async function testConnection(username: string, password: string, basePath: string): Promise<{ 
  success: boolean; 
  status?: number; 
  error?: string;
  rootFolders?: string[];
  basePathFiles?: string[];
  basePathFolders?: string[];
}> {
  const token = btoa(`${username}:${password}`);
  
  const knownFiles = ['Chat.md', 'Later.md', 'Help.md', 'Readme.md'];
  const pathsToTest = ['/笔记', '/我的坚果云/笔记', '/'];
  const pathResults: { path: string; status: number; files: string[]; folders: string[] }[] = [];

  for (const testPath of pathsToTest) {
    const result = { path: testPath, status: 0, files: [], folders: [] };
    
    for (const file of knownFiles) {
      const encodedPath = encodePath(`${testPath}/${file}`);
      const response = await fetch(`${NUTSTORE_WEBDAV_URL}${encodedPath}`, {
        method: 'GET',
        headers: { Authorization: `Basic ${token}` },
        mode: 'cors',
      });
      
      if (response.status === 401) {
        return { success: false, status: 401, error: '账号或密码错误' };
      }
      
      if (response.ok) {
        result.files.push(file);
        result.status = response.status;
      }
    }
    
    if (testPath === '/') {
      result.folders = result.files.length > 0 ? ['我的坚果云'] : [];
    }
    
    pathResults.push(result);
  }

  const rootFolders = pathResults.find(r => r.path === '/')?.folders || [];
  const targetResult = pathResults.find(r => r.path === basePath);

  if (pathResults.every(r => r.status === 0)) {
    return { success: false, status: 401, error: '账号或密码错误' };
  }

  return { 
    success: true, 
    rootFolders,
    basePathFiles: targetResult?.files || [],
    basePathFolders: targetResult?.folders || [],
  };
}

export async function listFilesmdFiles(basePath: string): Promise<{ 
  success: boolean; 
  files?: string[]; 
  folders?: string[];
  error?: string;
}> {
  try {
    const encodedPath = encodePath(basePath);
    const response = await makeNutstoreRequest(encodedPath, {
      method: 'PROPFIND',
      headers: { 'Depth': '1' },
    });
    
    if (!response.ok) {
      return { success: false, error: `请求失败 (${response.status})` };
    }
    
    const text = await response.text();
    const responses = await parseWebDAVResponse(text);
    const files: string[] = [];
    const folders: string[] = [];
    const dirName = basePath.split('/').filter(Boolean).pop();
    
    for (const { href } of responses) {
      const name = decodeURIComponent(href.split('/').filter(Boolean).pop() || '');
      if (name && name !== dirName && name !== 'dav') {
        if (name.endsWith('.md')) {
          files.push(name);
        } else if (!name.includes('.')) {
          folders.push(name);
        } else {
          files.push(name);
        }
      }
    }
    
    return { success: true, files, folders };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : '未知错误' };
  }
}

export async function readFile(path: string): Promise<{ 
  success: boolean; 
  content?: string;
  error?: string;
}> {
  try {
    const response = await makeNutstoreRequest(path, { method: 'GET' });
    
    if (!response.ok) {
      return { success: false, error: `读取失败 (${response.status})` };
    }
    
    const content = await response.text();
    return { success: true, content };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : '未知错误' };
  }
}

export async function writeFile(path: string, content: string): Promise<{ 
  success: boolean; 
  error?: string;
}> {
  try {
    const response = await makeNutstoreRequest(path, {
      method: 'PUT',
      headers: { 'Content-Type': 'text/markdown; charset=utf-8' },
      body: content,
    });
    
    if (!response.ok) {
      return { success: false, error: `写入失败 (${response.status})` };
    }
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : '未知错误' };
  }
}

export async function loadEntries(basePath: string): Promise<MarkdownEntry[]> {
  const cached = localStorage.getItem(LOCAL_CACHE_KEY);
  if (cached) {
    try {
      return JSON.parse(cached);
    } catch {
      localStorage.removeItem(LOCAL_CACHE_KEY);
    }
  }

  try {
    const creds = getCredentials();
    if (!creds) {
      return [];
    }

    const response = await fetchWithTimeout(`${API_BASE_URL}/nutstore/entries`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username: creds.username,
        password: creds.password,
        basePath,
      }),
    }, 15000);

    const data = await response.json();
    
    if (data.entries) {
      const allEntries: MarkdownEntry[] = [];
      for (const { fileName, content } of data.entries) {
        const entries = parseMarkdownFile(content, fileName);
        allEntries.push(...entries);
      }
      localStorage.setItem(LOCAL_CACHE_KEY, JSON.stringify(allEntries));
      return allEntries;
    }
    
    return [];
  } catch (error) {
    console.error('加载条目失败:', error);
    return [];
  }
}

export async function appendToFile(basePath: string, content: string, type: 'chat' | 'todo' | 'journal'): Promise<boolean> {
  try {
    const creds = getCredentials();
    if (!creds) {
      return false;
    }

    const response = await fetchWithTimeout(`${API_BASE_URL}/nutstore/append`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username: creds.username,
        password: creds.password,
        basePath,
        content,
        type,
      }),
    }, 15000);

    const data = await response.json();
    
    if (data.success) {
      localStorage.removeItem(LOCAL_CACHE_KEY);
    }
    
    return data.success;
  } catch {
    return false;
  }
}
